-- Hand-written below.

-- Product images uploaded from the admin. Public read (the storefront shows
-- them); there is no insert/update/delete policy for anon or authenticated, so
-- only the server (service role, after requireAdmin) can write. The bucket also
-- enforces the type and size limits the upload action validates.
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
  'product-images',
  'product-images',
  true,
  2097152,
  ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/avif']
)
ON CONFLICT (id) DO UPDATE
SET public = EXCLUDED.public,
    file_size_limit = EXCLUDED.file_size_limit,
    allowed_mime_types = EXCLUDED.allowed_mime_types;

-- cancel_order now also takes a cancelled PAID order out of the products'
-- soldCount (it was added when the order was paid). Same contract otherwise:
-- idempotent, row-locked, releases stock and coupon exactly once.
CREATE OR REPLACE FUNCTION public.cancel_order(p_order_id uuid, p_actor uuid, p_note text)
RETURNS boolean
LANGUAGE plpgsql
SET search_path = ''
AS $$
DECLARE
  previous public."OrderStatus";
BEGIN
  SELECT o.status INTO previous FROM public."Order" o WHERE o.id = p_order_id FOR UPDATE;
  IF previous IS NULL OR previous NOT IN ('PENDING', 'PAID') THEN
    RETURN false;
  END IF;

  UPDATE public."Order"
  SET status = 'CANCELLED', "cancelledAt" = now(), "updatedAt" = now()
  WHERE id = p_order_id;

  UPDATE public."ProductVariant" v
  SET stock = v.stock + reserved.quantity
  FROM (
    SELECT i."variantId", sum(i.quantity)::int AS quantity
    FROM public."OrderItem" i
    WHERE i."orderId" = p_order_id
    GROUP BY i."variantId"
  ) reserved
  WHERE v.id = reserved."variantId";

  IF previous = 'PAID' THEN
    UPDATE public."Product" p
    SET "soldCount" = greatest(p."soldCount" - sold.quantity, 0)
    FROM (
      SELECT i."productId", sum(i.quantity)::int AS quantity
      FROM public."OrderItem" i
      WHERE i."orderId" = p_order_id
      GROUP BY i."productId"
    ) sold
    WHERE p.id = sold."productId";
  END IF;

  WITH released AS (
    DELETE FROM public."CouponRedemption" r WHERE r."orderId" = p_order_id RETURNING r."couponId"
  )
  UPDATE public."Coupon" c
  SET "usedCount" = c."usedCount" - 1, "updatedAt" = now()
  FROM released
  WHERE c.id = released."couponId";

  UPDATE public."Payment" p
  SET status = 'VOIDED', "updatedAt" = now()
  WHERE p."orderId" = p_order_id AND p.status = 'PENDING';

  INSERT INTO public."OrderStatusHistory" ("id", "orderId", "from", "to", "changedById", "note")
  VALUES (gen_random_uuid(), p_order_id, previous, 'CANCELLED', p_actor, p_note);

  RETURN true;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.cancel_order(uuid, uuid, text) FROM PUBLIC, anon, authenticated;
